use clap::Subcommand;
use clap::ValueEnum;

use heisenberg_project_model::constants::CARGO_BUILD_TABLE;
use heisenberg_project_model::constants::CARGO_ENVIRONMENT_TABLE;
use heisenberg_project_model::constants::CARGO_RUSTC;
use heisenberg_project_model::constants::CARGO_RUSTC_WORKSPACE_WRAPPER;
use heisenberg_project_model::constants::CARGO_RUSTC_WRAPPER;
use heisenberg_project_model::constants::CARGO_RUSTFLAGS;
use heisenberg_project_model::constants::CARGO_TARGET_TABLE;
use heisenberg_project_model::constants::CLIPPY_ARGUMENTS_VARIABLE;
use heisenberg_project_model::constants::CLIPPY_CONFIGURATION_DIRECTORY_VARIABLE;
use heisenberg_project_model::constants::CLIPPY_CONFIGURATION_FILE;
use heisenberg_project_model::constants::CLIPPY_HIDDEN_CONFIGURATION_FILE;
use heisenberg_project_model::constants::COMPILER_VARIABLES;
use heisenberg_project_model::constants::NIGHTLY_BOOTSTRAP_VARIABLE;
use heisenberg_project_model::constants::NIGHTLY_FEATURE_VARIABLES;
use heisenberg_project_model::constants::RUSTFLAGS_VARIABLES;
use heisenberg_project_model::supported_target_list::SupportedTargetList;

use crate::check_command::CheckCommand;
use crate::constants::CODE_ACTIVE_IN_NO_CONFIGURATION;
use crate::constants::SUPPORTED_RUST_VERSION;
use crate::constants::TESTS_ONLY_PACKAGE_WITHOUT_TEST_LIBRARIES;
use crate::explain_command::ExplainCommand;
use crate::issue_text::IssueText;
use crate::issue_type::IssueType;

#[derive(Debug, Subcommand)]
pub enum HeisenbergSubcommand {
    #[command(
        about = "Report module dependency cycles and structural violations in every crate of a Cargo workspace, in the configurations it declares",
        long_about = format!("Report module dependency cycles and structural violations in every crate of a Cargo workspace, in the configurations it declares.\n\nSettings: the workspace root manifest holds every Heisenberg setting in its [workspace.metadata.heisenberg] table, whose required configurations array lists the configurations the workspace supports, each a table of a unique, nonempty name, a target among {}, default_features, which keeps or leaves out the default features, and features, the names of features that workspace members define, each listed once, no two configurations sharing their target and features, and whose optional out_dirs table declares, for a package of the workspace, member or dependency, whose build script cannot run on every host, a configurations table that gives, for each declared configuration, a directory, relative to the workspace root, with the files the build script writes to OUT_DIR, and the cfgs and env the build script emits; that build script then never runs, and the declared files, cfgs and env stand in for its output; its optional test_crates list names the workspace members that hold only code for tests. A missing table, an unknown key, an empty configuration list, an empty or repeated configuration name, a configuration with an unknown target, with a feature that no workspace member defines or with a feature listed twice, two configurations with the same target and features, a configuration that selects features other than the default ones in a workspace that uses resolver 1 with a root package and other members, where cargo applies a feature selection to the root package only, an out-dir for a package the workspace does not resolve, for a name that several resolved versions share or for a package without a build script, an out-dir directory outside the workspace or that cannot be read, an out-dir without the output of a declared configuration or with the output of an undeclared configuration, and a declared cfg that does not parse fail the run. A test_crates entry that is not a workspace member, that is listed twice, whose package can be published, or that a member other than a test crate depends on through a normal or build dependency is a violation, and an entry that fails these conditions is not a test crate. No setting exempts code from any rule: test_crates declares which members are test code, and Heisenberg verifies the declaration.\n\nPrecondition: rustc {SUPPORTED_RUST_VERSION} compiles the workspace in every analysed configuration with the standard library of its target installed, Cargo.lock is up to date, the cargo home holds every package of Cargo.lock (`cargo fetch`), the build runs from the workspace directory with the environment Heisenberg runs with and without --config arguments, and clippy runs without command-line arguments. An environment variable whose name or value is not UTF-8, {rustflags_variables}, {compiler_variables}, {CLIPPY_ARGUMENTS_VARIABLE}, {CLIPPY_CONFIGURATION_DIRECTORY_VARIABLE} or {nightly_feature_variables} in the environment, a workspace directory that is not the root of its cargo workspace, a workspace member or crate root outside the workspace root, a package whose metadata cargo_metadata cannot read, a crate root that two targets share or that cannot be read, a metabuild script, which has no source file, a workspace root, target directory or crate root that is not an absolute UTF-8 path, a {CLIPPY_CONFIGURATION_FILE} or {CLIPPY_HIDDEN_CONFIGURATION_FILE} that discovery finds and cannot read, or that is the only one in its directory and is not valid TOML, {CARGO_RUSTFLAGS} in the [{CARGO_BUILD_TABLE}] or [{CARGO_TARGET_TABLE}] tables of the cargo configuration or in the {build_rustflags_variable} and {target_rustflags_variable} variables of a supported target, {CARGO_RUSTC}, {CARGO_RUSTC_WORKSPACE_WRAPPER} or {CARGO_RUSTC_WRAPPER} in the [{CARGO_BUILD_TABLE}] table of the cargo configuration, including through the environment variables that set them, and {CLIPPY_ARGUMENTS_VARIABLE}, {CLIPPY_CONFIGURATION_DIRECTORY_VARIABLE} or {NIGHTLY_BOOTSTRAP_VARIABLE} in the [{CARGO_ENVIRONMENT_TABLE}] table of the cargo configuration, under any letter case, fail the run.\n\nAnalysis: Values that the [env] table of the cargo configuration declares reach the analysis as cargo resolves them, OUT_DIR and the cfgs and env a build script emits come from running it, or from its out_dirs declaration, and an env! or option_env! of a variable that none of them sets expands as rust-analyzer expands it. The analysis enables debug assertions, the features of the analysed configuration, each on every workspace member that defines it, as cargo does, and test only for the targets cargo builds with libtest's harness, as rustc's --test does: a target with harness = false, or one that cargo neither tests nor benchmarks, such as a build script or an example, is analysed without it. Every run analyses the declared configurations that --configuration selects, which it requires, and a --configuration the workspace does not declare or selects twice fails the run. Build scripts and procedural macros run: for each analysed configuration, cargo builds the procedural macros offline with the rustc of the sysroot and runs the build scripts, apart from those out_dirs declares, and the sysroot's rust-analyzer-proc-macro-srv expands the procedural macros, whose output is analysed like any macro expansion, its input where it is written and the tokens it generates trusted, and a build script that fails or emits a cfg that does not parse, one that needs a build script out_dirs declares, a build script output that cannot be read, a procedural macro that fails to build or that the server cannot load, a declared target without its standard library, a sysroot without rustc and a sysroot without the server, or whose server cannot start, fail the run. Every decision is semantic, as rust-analyzer resolves the code. Shared module files are analysed in every crate that includes them. The public item, constant, item order, method order and integration test target rules apply to items written in module files, including those that a macro_rules! macro of the crate writes, and the name, tuple and parameter rules to the text written in them; an item that an attribute macro rewrites is analysed through the items of its expansion that rust-analyzer maps back to it, and the rest of the expansion, like the items that procedural macros and the macros of other crates generate, is trusted. Derive macro output is analysed like any macro expansion, except that of the built-in derives that rust-analyzer records as impls of their trait without expanding them, which is trusted; text written outside a crate's module files, such as in other crates or in the build script output that include! brings in, is trusted, and results reflect the files on disk, including generated ones. Test code is every target of a test crate, every integration test target and every module that cfg(test) gates, inline or in its own file and under any name; a test crate is a workspace member that test_crates lists, whose package cannot be published (publish = false), and that no member other than a test crate depends on through a normal or build dependency.\n\nReport: Issues are grouped by type, in one section per type: a `<IssueType>: <count> violation(s)` line, a line that states the purpose of the rule and what to do, an empty line, and one `- <file>[:<line>:<column>]: <message>` line per issue, followed, four spaces in, by its source line when it has one and by further indented lines with its details, such as the dependencies of a cycle, the inclusions of a shared module file, the failing expansions of a macro call or the impl blocks of a flagged type. Each issue is reported once, at the name of the item it concerns; when it holds only in some of the crate targets or configurations that analyse its file, the message names them. A cause and its direct consequences form one issue. A partial run, one that leaves out a declared configuration, names the configurations it left out after the analysed ones and does not evaluate {code_active_in_no_configuration_name} or the empty-library check of {tests_only_package_name}, which hold only over every declared configuration; a partial run without issues exits as compliant.\n\nRules:\n{rules}\n\nRun `heisenberg explain <ISSUE_TYPE>` for the definition of a rule, why it exists and how to satisfy it.", SupportedTargetList,
            build_rustflags_variable = format!("CARGO_{CARGO_BUILD_TABLE}_{CARGO_RUSTFLAGS}").to_uppercase(),
            compiler_variables = COMPILER_VARIABLES.join(", "),
            nightly_feature_variables = NIGHTLY_FEATURE_VARIABLES.join(", "),
            rules = IssueType::value_variants().iter().map(|issue_type| {
                let IssueText { name, summary, .. } = issue_type.text();

                format!("  {name}: {summary}")
            }).collect::<Vec<String>>().join("\n"),
            rustflags_variables = RUSTFLAGS_VARIABLES.join(", "),
            code_active_in_no_configuration_name = CODE_ACTIVE_IN_NO_CONFIGURATION.name,
            tests_only_package_name = TESTS_ONLY_PACKAGE_WITHOUT_TEST_LIBRARIES.name,
            target_rustflags_variable = format!("CARGO_{CARGO_TARGET_TABLE}_<TRIPLE>_{CARGO_RUSTFLAGS}").to_uppercase())
    )]
    Check(CheckCommand),
    #[command(about = "Print the definition of a rule, why it exists and how to satisfy it")]
    Explain(ExplainCommand),
}
